function out($data, $code=200){
    while(ob_get_level()>0) ob_end_clean();
    http_response_code($code);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($data, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    exit;
}
set_exception_handler(function(Throwable $e){ error_log('Panel API: '.$e->getMessage()); out(['ok'=>false,'message'=>'Server xatosi.'],500); });
register_shutdown_function(function(){ $e=error_get_last(); if($e && in_array($e['type'],[E_ERROR,E_PARSE,E_CORE_ERROR,E_COMPILE_ERROR],true)){ while(ob_get_level()>0) ob_end_clean(); http_response_code(500); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok'=>false,'message'=>'Server xatosi.'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); } });
function db(){ static $loaded=false,$c=null; if($loaded)return $c; $loaded=true; @include __DIR__.'/conf.php'; if(isset($conn)&&$conn instanceof mysqli&&!$conn->connect_errno){$conn->set_charset('utf8mb4');return $conn;} return null; }
function businessStart(){ $d=strtotime(date('Y-m-d').' 06:00:00'); return date('Y-m-d H:i:s', time()>=$d?$d:strtotime('-1 day',$d)); }
function businessEnd(){ return date('Y-m-d H:i:s',strtotime(businessStart().' +18 hours')); }
function ensureSchema(mysqli $c){
    $c->query("CREATE TABLE IF NOT EXISTS admin_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_table VARCHAR(128) NULL,source_key VARCHAR(191) NULL,customer_name VARCHAR(190) NOT NULL DEFAULT '',phone VARCHAR(60) NOT NULL DEFAULT '',address TEXT NULL,note TEXT NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,payment_method VARCHAR(20) NOT NULL DEFAULT 'cash',lat DECIMAL(10,7) NULL,lng DECIMAL(10,7) NULL,status VARCHAR(40) NOT NULL DEFAULT 'new',courier_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    foreach(["payment_method VARCHAR(20) NOT NULL DEFAULT 'cash'","lat DECIMAL(10,7) NULL","lng DECIMAL(10,7) NULL","courier_id BIGINT UNSIGNED NULL"] as $col){try{$c->query('ALTER TABLE admin_orders ADD COLUMN '.$col);}catch(Throwable $e){}}
    $c->query("CREATE TABLE IF NOT EXISTS couriers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,phone VARCHAR(60) NOT NULL UNIQUE,pin_hash VARCHAR(255) NULL,auth_token VARCHAR(128) NULL,status VARCHAR(30) NOT NULL DEFAULT 'offline',last_seen TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    foreach(["pin_hash VARCHAR(255) NULL","auth_token VARCHAR(128) NULL","status VARCHAR(30) NOT NULL DEFAULT 'offline'","last_seen TIMESTAMP NULL"] as $col){try{$c->query('ALTER TABLE couriers ADD COLUMN '.$col);}catch(Throwable $e){}}
    $c->query("CREATE TABLE IF NOT EXISTS customer_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NULL,name VARCHAR(190) NOT NULL,phone VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(190) NULL,address TEXT NULL,password_hash VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $c->query("CREATE TABLE IF NOT EXISTS admin_settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $c->query("INSERT IGNORE INTO admin_settings(setting_key,setting_value) VALUES('store_name','Lavash N1'),('phone','+998 99 830 56 03'),('address','Samarqand, Chelak 78-Maktab oldi'),('delivery_note','Tez va issiq dastavka'),('delivery_fee','0'),('promo_enabled','1'),('promo_title','Bugungi aksiya'),('promo_text','Lavash + kartoshka + ichimlik')");
}
function courierId(mysqli $c){ $p=COURIER_PHONE; $st=$c->prepare('SELECT id FROM couriers WHERE phone=? LIMIT 1'); $st->bind_param('s',$p);$st->execute();$r=$st->get_result()->fetch_assoc(); if($r)return (int)$r['id']; $h=password_hash(PANEL_PASS,PASSWORD_DEFAULT);$n='Daler Lavash';$t=COURIER_TOKEN;$st=$c->prepare("INSERT INTO couriers(name,phone,pin_hash,auth_token,status) VALUES(?,?,?,?, 'offline')");$st->bind_param('ssss',$n,$p,$h,$t);$st->execute();return (int)$c->insert_id; }
$action=(string)($_REQUEST['action']??'');
try{
    if($action==='health'){ $c=db(); out(['ok'=>true,'server'=>true,'database'=>(bool)$c,'business_start'=>businessStart(),'business_end'=>businessEnd(),'time'=>date('c')]); }
